# -*- coding: utf-8 -*-
"""Texts for the new Organ Labs (mouth, gut, liver, knee): parts and steps, English, Hindi, Hinglish."""
import json
APP = '/home/claude/duet-lms-media/body'
def T(en, hi, hg): return {'en': en, 'hi': hi, 'hg': hg}
P = {}
def part(pid, sys, name, job, process): P[pid] = {'name': name, 'job': job, 'sys': sys, 'process': process}
D = 'digestive'
# ---------------------------------------------------------------- intestines
part('bile_opening', D, T("Opening for bile and pancreatic juice (ampulla)", "पित्त और अग्न्याशय रस का द्वार (एम्पुला)", "Bile aur pancreatic juice ka darwaza (ampulla)"),
  T("A small opening in the wall of the duodenum where bile from the liver and juice from the pancreas pour in.", "ग्रहणी (ड्यूडेनम) की दीवार में एक छोटा द्वार, जहाँ से लिवर का पित्त (बाइल) और अग्न्याशय (पैंक्रियाज़) का रस अंदर आता है।", "Duodenum ki deewar mein ek chhota darwaza, jahan se liver ka bile aur pancreas ka juice andar aata hai."),
  T("The bile duct and the pancreatic duct join just before they reach the duodenum and open together on a small bump called the papilla. A ring of muscle around it, the sphincter, opens when food arrives, so bile and pancreatic juice mix with the food at the right time.",
    "पित्त नली (बाइल डक्ट) और अग्न्याशय की नली ग्रहणी तक पहुँचने से ठीक पहले मिल जाती हैं और एक छोटे उभार, पैपिला, पर साथ में खुलती हैं। इसके चारों ओर मांसपेशी का एक छल्ला, स्फिंक्टर, खाना आने पर खुलता है, ताकि पित्त और अग्न्याशय रस सही समय पर खाने में मिलें।",
    "Bile duct aur pancreatic duct duodenum tak pahunchne se theek pehle mil jaati hain aur ek chhote ubhaar, papilla, par saath mein khulti hain. Iske chaaron taraf muscle ka ek chhalla, sphincter, khaana aane par khulta hai, taaki bile aur pancreatic juice sahi samay par khaane mein milein."))
part('jejunum', D, T("Jejunum (middle small intestine)", "मध्यांत्र (जेजुनम)", "Jejunum (small intestine ka beech ka hissa)"),
  T("The middle part of the small intestine, where most of the digested food is taken into the blood.", "छोटी आँत का बीच का भाग, जहाँ पचा हुआ ज़्यादातर भोजन रक्त में अवशोषित (एब्ज़ॉर्ब) होता है।", "Small intestine ka beech ka hissa, jahan pacha hua zyaadatar khaana blood mein absorb hota hai."),
  T("The jejunum is about 2.5 metres long and lies coiled in the upper left belly. Its inner wall has deep folds covered with millions of tiny finger-like villi. Sugars, amino acids and fats pass through the thin villi into tiny blood vessels and lymph vessels.",
    "मध्यांत्र (जेजुनम) लगभग 2.5 मीटर लंबी होती है और पेट के ऊपरी बाएँ भाग में कुंडली की तरह मुड़ी रहती है। इसकी अंदर की दीवार पर गहरी सिलवटें होती हैं, जिन पर लाखों छोटे उँगली जैसे दीर्घरोम (विलाई) होते हैं। शक्कर, अमीनो एसिड और वसा (फ़ैट) इन पतले विलाई से होकर छोटी रक्त वाहिकाओं और लसीका वाहिकाओं में चले जाते हैं।",
    "Jejunum lagbhag 2.5 metre lambi hoti hai aur pet ke upar baayein hisse mein coil ki tarah mudi rehti hai. Iski andar ki deewar par gehri silvatein hoti hain, jin par laakhon chhote ungli jaise villi hote hain. Sugar, amino acids aur fat in patle villi se hokar chhoti blood vessels aur lymph vessels mein chale jaate hain."))
part('ileum', D, T("Ileum (last part of the small intestine)", "शेषांत्र (इलियम)", "Ileum (small intestine ka aakhri hissa)"),
  T("The longest and last part of the small intestine; it takes in what is left, including vitamin B12 and bile salts.", "छोटी आँत का सबसे लंबा और आख़िरी भाग; यह बचा हुआ पोषण, विटामिन B12 और पित्त लवण (बाइल सॉल्ट) भी अवशोषित करता है।", "Small intestine ka sabse lamba aur aakhri hissa; ye bacha hua nutrition, vitamin B12 aur bile salts bhi absorb karta hai."),
  T("The ileum is about 3.5 metres long and coils in the lower right belly. Its villi are shorter than in the jejunum. It absorbs vitamin B12 and returns bile salts to the blood, so the liver can use them again. At its end, a valve opens into the large intestine.",
    "शेषांत्र (इलियम) लगभग 3.5 मीटर लंबी है और पेट के निचले दाएँ भाग में कुंडली बनाती है। इसके विलाई मध्यांत्र से छोटे होते हैं। यह विटामिन B12 अवशोषित करती है और पित्त लवण को वापस रक्त में भेजती है, ताकि लिवर उन्हें फिर से इस्तेमाल कर सके। इसके अंत में एक वाल्व बड़ी आँत में खुलता है।",
    "Ileum lagbhag 3.5 metre lambi hai aur pet ke neeche daayein hisse mein coil banati hai. Iske villi jejunum se chhote hote hain. Ye vitamin B12 absorb karti hai aur bile salts ko wapas blood mein bhejti hai, taaki liver unhe phir se use kar sake. Iske end par ek valve large intestine mein khulta hai."))
part('ileocecal_valve', D, T("Ileocaecal valve", "शेषांत्र-अंधनाल वाल्व (इलियोसीकल वाल्व)", "Ileocaecal valve"),
  T("A one-way gate between the small and large intestine that lets the remains of food pass forward but not back.", "छोटी और बड़ी आँत के बीच एक-तरफ़ा दरवाज़ा, जो भोजन के बचे हिस्से को आगे जाने देता है पर वापस नहीं आने देता।", "Small aur large intestine ke beech ek-taraf darwaza, jo khaane ke bache hisse ko aage jaane deta hai par wapas nahi aane deta."),
  T("Two lips of the ileum push into the caecum. When the ileum squeezes, the lips open and the liquid remains of food enter the large intestine. When the caecum fills, the lips press shut, which stops the bacteria of the large intestine from moving back into the small intestine.",
    "शेषांत्र के दो होंठ जैसे किनारे अंधनाल (सीकम) में घुसे रहते हैं। जब शेषांत्र सिकुड़ती है, ये किनारे खुलते हैं और भोजन का तरल बचा भाग बड़ी आँत में चला जाता है। जब अंधनाल भर जाती है, ये किनारे दबकर बंद हो जाते हैं, जिससे बड़ी आँत के बैक्टीरिया वापस छोटी आँत में नहीं जा पाते।",
    "Ileum ke do hothon jaise kinaare caecum mein ghuse rehte hain. Jab ileum sikudti hai, ye kinaare khulte hain aur khaane ka liquid bacha hissa large intestine mein chala jaata hai. Jab caecum bhar jaati hai, ye kinaare dabkar band ho jaate hain, jisse large intestine ke bacteria wapas small intestine mein nahi ja paate."))
part('caecum', D, T("Caecum", "अंधनाल (सीकम)", "Caecum"),
  T("A pouch at the start of the large intestine that receives the remains of food from the small intestine.", "बड़ी आँत की शुरुआत में एक थैली, जिसमें छोटी आँत से भोजन का बचा हुआ हिस्सा आता है।", "Large intestine ki shuruaat mein ek thaili, jismein small intestine se khaane ka bacha hua hissa aata hai."),
  T("The caecum sits in the lower right belly. Below the ileocaecal valve it ends in a blind pouch, with the narrow appendix hanging from it. Here water starts to be taken back and gut bacteria begin to break down fibre.",
    "अंधनाल (सीकम) पेट के निचले दाएँ भाग में होती है। इलियोसीकल वाल्व के नीचे यह एक बंद थैली के रूप में ख़त्म होती है, और इससे पतली परिशेषिका (अपेंडिक्स) लटकती है। यहाँ से पानी वापस सोखना शुरू होता है और आँत के बैक्टीरिया रेशे (फ़ाइबर) को तोड़ना शुरू करते हैं।",
    "Caecum pet ke neeche daayein hisse mein hoti hai. Ileocaecal valve ke neeche ye ek band thaili ki tarah khatam hoti hai, aur isse patla appendix latakta hai. Yahan se paani wapas sokhna shuru hota hai aur gut ke bacteria fibre ko todna shuru karte hain."))
part('rectum', D, T("Rectum", "मलाशय (रेक्टम)", "Rectum"),
  T("The last part of the large intestine, which stores waste (stool) until it is passed out of the body.", "बड़ी आँत का आख़िरी भाग, जो मल को तब तक रखता है जब तक वह शरीर से बाहर न निकल जाए।", "Large intestine ka aakhri hissa, jo stool ko tab tak rakhta hai jab tak wo body se bahar na nikal jaaye."),
  T("When the rectum fills and its walls stretch, nerves send a message to the brain that it is time to go to the toilet. The muscles of the anus relax and the stool is pushed out. Passing out undigested waste is called egestion.",
    "जब मलाशय भर जाता है और उसकी दीवारें खिंचती हैं, तो तंत्रिकाएँ (नर्व्स) मस्तिष्क को संदेश भेजती हैं कि शौचालय जाने का समय है। गुदा (एनस) की मांसपेशियाँ ढीली होती हैं और मल बाहर धकेल दिया जाता है। बिना पचे कचरे को बाहर निकालना बहिःक्षेपण (इजेशन) कहलाता है।",
    "Jab rectum bhar jaata hai aur uski deewarein khinchti hain, to nerves brain ko message bhejti hain ki toilet jaane ka time hai. Anus ki muscles dheeli hoti hain aur stool bahar dhakel diya jaata hai. Bina pache waste ko bahar nikaalna egestion kehlata hai."))
# ---------------------------------------------------------------- mouth
part('teeth', D, T("Teeth", "दाँत", "Daant (teeth)"),
  T("Cut, tear and grind food into small pieces, so it can be swallowed and digested.", "भोजन को काटते, फाड़ते और पीसकर छोटे टुकड़ों में बदलते हैं, ताकि वह निगला और पचाया जा सके।", "Khaane ko kaatte, phaadte aur peeskar chhote tukdon mein badalte hain, taaki wo nigla aur pachaya ja sake."),
  T("An adult has 32 teeth. Flat incisors at the front cut, pointed canines tear, and broad premolars and molars at the back crush and grind. Children have 20 milk teeth, which are replaced by permanent teeth from about the age of six.",
    "बड़ों के 32 दाँत होते हैं। आगे के चपटे कृंतक (इनसाइज़र) काटते हैं, नुकीले रदनक (कैनाइन) फाड़ते हैं, और पीछे के चौड़े अग्रचर्वणक (प्रीमोलर) और चर्वणक (मोलर) कुचलते और पीसते हैं। बच्चों के 20 दूध के दाँत होते हैं, जिनकी जगह लगभग छह साल की उम्र से स्थायी दाँत आते हैं।",
    "Badon ke 32 daant hote hain. Aage ke chapte incisors kaatte hain, nukeele canines phaadte hain, aur peeche ke chaude premolars aur molars kuchalte aur peeste hain. Bachchon ke 20 doodh ke daant hote hain, jinki jagah lagbhag chhah saal ki umar se permanent daant aate hain."))
part('taste_buds', D, T("Taste papillae (with taste buds)", "स्वाद अंकुर (पैपिला, स्वाद कलिकाओं के साथ)", "Taste papillae (taste buds ke saath)"),
  T("Small bumps on the tongue that hold taste buds, which sense sweet, salty, sour, bitter and savoury (umami) tastes.", "जीभ पर छोटे उभार, जिनमें स्वाद कलिकाएँ (टेस्ट बड्स) होती हैं; ये मीठा, नमकीन, खट्टा, कड़वा और उमामी (शोरबे जैसा) स्वाद पहचानती हैं।", "Jeebh par chhote ubhaar, jinmein taste buds hote hain; ye meetha, namkeen, khatta, kadwa aur umami (shorbe jaisa) swaad pehchaante hain."),
  T("Mushroom-shaped papillae are scattered over the front of the tongue, and a V-shaped row of large round papillae lies near the back. Each taste bud has taste cells that react to substances dissolved in saliva and send signals along nerves to the brain. All five tastes can be sensed all over the tongue.",
    "मशरूम जैसे पैपिला जीभ के आगे के भाग पर बिखरे होते हैं, और जीभ के पीछे की ओर बड़े गोल पैपिला की V आकार की एक पंक्ति होती है। हर स्वाद कलिका में स्वाद कोशिकाएँ होती हैं, जो लार में घुले पदार्थों पर प्रतिक्रिया करती हैं और तंत्रिकाओं से मस्तिष्क को संदेश भेजती हैं। पाँचों स्वाद पूरी जीभ पर महसूस किए जा सकते हैं।",
    "Mushroom jaise papillae jeebh ke aage ke hisse par bikhre hote hain, aur jeebh ke peeche ki taraf bade gol papillae ki V shape ki ek line hoti hai. Har taste bud mein taste cells hoti hain, jo saliva mein ghule padarthon par react karti hain aur nerves se brain ko message bhejti hain. Paanchon swaad poori jeebh par mehsoos kiye ja sakte hain."))
part('hard_palate', D, T("Hard palate", "कठोर तालु", "Hard palate (sakht taalu)"),
  T("The bony front part of the roof of the mouth, which separates the mouth from the nose.", "मुँह की छत का हड्डी वाला अगला भाग, जो मुँह को नाक से अलग करता है।", "Munh ki chhat ka haddi wala agla hissa, jo munh ko naak se alag karta hai."),
  T("The tongue presses food against the hard palate to squash it and roll it into a soft ball. Its ridges help to grip the food. Because the palate separates the mouth from the nose, we can chew and breathe at the same time.",
    "जीभ भोजन को कठोर तालु से दबाकर कुचलती है और उसे एक नरम गोले में लपेटती है। इस पर बनी धारियाँ भोजन को पकड़ने में मदद करती हैं। क्योंकि तालु मुँह को नाक से अलग रखता है, इसलिए हम चबाते हुए साँस भी ले सकते हैं।",
    "Jeebh khaane ko hard palate se dabaakar kuchalti hai aur use ek naram gole mein lapet-ti hai. Is par bani dhaariyaan khaane ko pakadne mein madad karti hain. Kyunki palate munh ko naak se alag rakhta hai, isliye hum chabaate hue saans bhi le sakte hain."))
part('sublingual_gland', D, T("Sublingual glands", "अधोजिह्वा ग्रंथियाँ (सबलिंगुअल ग्लैंड)", "Sublingual glands"),
  T("The smallest pair of salivary glands, under the tongue, which make thick, slimy saliva.", "लार ग्रंथियों की सबसे छोटी जोड़ी, जो जीभ के नीचे होती है और गाढ़ी, चिपचिपी लार बनाती है।", "Salivary glands ki sabse chhoti jodi, jo jeebh ke neeche hoti hai aur gaadhi, chipchipi saliva banati hai."),
  T("The sublingual glands lie in the floor of the mouth, just under the tongue, and open through many tiny ducts. Their saliva is rich in mucus, which makes food slippery, so it slides down the throat easily.",
    "अधोजिह्वा ग्रंथियाँ मुँह के तल में, जीभ के ठीक नीचे होती हैं और कई छोटी नलियों से खुलती हैं। इनकी लार में श्लेष्मा (म्यूकस) ज़्यादा होता है, जो भोजन को चिकना बनाता है, ताकि वह आसानी से गले से नीचे फिसल जाए।",
    "Sublingual glands munh ke floor mein, jeebh ke theek neeche hoti hain aur kai chhoti naliyon se khulti hain. Inki saliva mein mucus zyaada hota hai, jo khaane ko chikna banata hai, taaki wo aasaani se gale se neeche phisal jaaye."))
part('cheek_lining', D, T("Inner lining of the cheeks", "गालों की भीतरी परत", "Gaalon ki andar ki parat"),
  T("A soft, moist skin that lines the inside of the cheeks and keeps food between the teeth while chewing.", "गालों के अंदर की नरम, नम परत, जो चबाते समय भोजन को दाँतों के बीच रखती है।", "Gaalon ke andar ki naram, nam parat, jo chabaate samay khaane ko daanton ke beech rakhti hai."),
  T("The lining is kept wet by saliva. The cheek muscles under it push food back onto the teeth. Its cells wear away and are replaced every few days, which is why a cut inside the mouth heals quickly.",
    "यह परत लार से नम रहती है। इसके नीचे की गालों की मांसपेशियाँ भोजन को वापस दाँतों पर धकेलती हैं। इसकी कोशिकाएँ घिसती रहती हैं और कुछ ही दिनों में नई बन जाती हैं, इसीलिए मुँह के अंदर का घाव जल्दी भरता है।",
    "Ye parat saliva se nam rehti hai. Iske neeche ki gaalon ki muscles khaane ko wapas daanton par dhakelti hain. Iski cells ghisti rehti hain aur kuch hi dinon mein nayi ban jaati hain, isiliye munh ke andar ka ghaav jaldi bharta hai."))
part('mouth_floor', D, T("Floor of the mouth", "मुँह का तल", "Munh ka floor"),
  T("The soft area under the tongue, where the ducts of two pairs of salivary glands open.", "जीभ के नीचे का नरम भाग, जहाँ दो जोड़ी लार ग्रंथियों की नलियाँ खुलती हैं।", "Jeebh ke neeche ka naram hissa, jahan do jodi salivary glands ki naliyaan khulti hain."),
  T("Look under your tongue in a mirror: you can see a thin fold holding the tongue down and two small bumps beside it. Saliva from the submandibular glands comes out of these bumps, and the sublingual glands open all along the floor.",
    "शीशे में अपनी जीभ के नीचे देखिए: वहाँ जीभ को नीचे से थामे एक पतली झिल्ली और उसके पास दो छोटे उभार दिखते हैं। अधोहनु ग्रंथियों (सबमैंडिबुलर ग्लैंड) की लार इन्हीं उभारों से निकलती है, और अधोजिह्वा ग्रंथियाँ तल में जगह-जगह खुलती हैं।",
    "Sheeshe mein apni jeebh ke neeche dekhiye: wahan jeebh ko neeche se thaame ek patli jhilli aur uske paas do chhote ubhaar dikhte hain. Submandibular glands ki saliva inhi ubhaaron se nikalti hai, aur sublingual glands floor mein jagah-jagah khulti hain."))
# ---------------------------------------------------------------- knee
S = 'skeleton'
part('femoral_condyles', S, T("Knuckles of the thigh bone (femoral condyles)", "जाँघ की हड्डी के गोल सिरे (फ़ीमोरल कॉन्डाइल)", "Thigh bone ke gol sire (femoral condyles)"),
  T("Two rounded ends of the thigh bone that roll and glide on the shin bone when the knee bends.", "जाँघ की हड्डी (फ़ीमर) के दो गोल सिरे, जो घुटना मुड़ने पर पिंडली की हड्डी (टिबिया) पर लुढ़कते और फिसलते हैं।", "Thigh bone (femur) ke do gol sire, jo ghutna mudne par shin bone (tibia) par ludhakte aur phisalte hain."),
  T("The inner and outer condyles are covered with smooth cartilage. Between them is a deep notch where the cruciate ligaments attach. In front, a groove lets the kneecap slide up and down as the leg bends and straightens.",
    "अंदर और बाहर के दोनों गोल सिरे चिकनी उपास्थि (कार्टिलेज) से ढके होते हैं। उनके बीच एक गहरा खाँचा होता है, जहाँ क्रूसिएट लिगामेंट जुड़ते हैं। आगे की ओर एक नाली होती है, जिसमें पैर मुड़ने और सीधा होने पर घुटने की टोपी (पटेला) ऊपर-नीचे फिसलती है।",
    "Andar aur bahar ke dono gol sire chikni cartilage se dhake hote hain. Unke beech ek gehra khaancha hota hai, jahan cruciate ligaments judte hain. Aage ki taraf ek naali hoti hai, jismein pair mudne aur seedha hone par kneecap (patella) upar-neeche phisalti hai."))
part('meniscus', S, T("Menisci (knee cushions)", "मेनिस्कस (घुटने की गद्दियाँ)", "Menisci (ghutne ke cushion)"),
  T("Two C-shaped pads of tough cartilage on top of the shin bone that cushion the knee and spread the body's weight.", "पिंडली की हड्डी के ऊपर मज़बूत उपास्थि की दो C आकार की गद्दियाँ, जो घुटने को झटकों से बचाती हैं और शरीर का भार फैलाती हैं।", "Shin bone ke upar mazboot cartilage ki do C shape ki gaddiyaan, jo ghutne ko jhatkon se bachati hain aur body ka weight phailati hain."),
  T("The menisci fill the gap between the round knuckles of the thigh bone and the flat top of the shin bone, so the bones fit well. When you jump or run, they absorb the shock. A sudden twist of a bent knee, common in football and kabaddi, can tear a meniscus.",
    "मेनिस्कस जाँघ की हड्डी के गोल सिरों और पिंडली की हड्डी के चपटे ऊपरी भाग के बीच की जगह भरते हैं, ताकि हड्डियाँ अच्छी तरह बैठें। कूदते या दौड़ते समय ये झटका सोख लेते हैं। मुड़े घुटने का अचानक मरोड़, जो फ़ुटबॉल और कबड्डी में आम है, मेनिस्कस को फाड़ सकता है।",
    "Menisci thigh bone ke gol siron aur shin bone ke chapte upar wale hisse ke beech ki jagah bharte hain, taaki haddiyaan achchhi tarah baithein. Koodte ya daudte samay ye jhatka sokh lete hain. Mude ghutne ka achaanak marod, jo football aur kabaddi mein aam hai, meniscus ko phaad sakta hai."))
part('knee_cartilage', S, T("Joint cartilage (articular cartilage)", "जोड़ की उपास्थि (आर्टिकुलर कार्टिलेज)", "Joint ki cartilage (articular cartilage)"),
  T("A smooth, slippery layer on the ends of the bones that lets them move against each other without wearing away.", "हड्डियों के सिरों पर एक चिकनी, फिसलन भरी परत, जिससे हड्डियाँ बिना घिसे एक-दूसरे पर चल पाती हैं।", "Haddiyon ke siron par ek chikni, phisalan bhari parat, jisse haddiyaan bina ghise ek-doosre par chal paati hain."),
  T("Joint cartilage has no blood vessels; it is fed by the slippery synovial fluid inside the joint, which also oils it. Moving and exercising pump this fluid in and out. In old age the cartilage can thin and crack, making the joint stiff and painful (osteoarthritis).",
    "जोड़ की उपास्थि में रक्त वाहिकाएँ नहीं होतीं; इसे जोड़ के अंदर का चिकना सायनोवियल द्रव (फ़्लूइड) पोषण देता है, जो इसे तेल की तरह चिकना भी रखता है। चलने-फिरने और व्यायाम से यह द्रव अंदर-बाहर होता रहता है। बुढ़ापे में उपास्थि पतली होकर फट सकती है, जिससे जोड़ अकड़ जाता है और दर्द होता है (ऑस्टियोआर्थराइटिस)।",
    "Joint ki cartilage mein blood vessels nahi hoti; ise joint ke andar ka chikna synovial fluid nutrition deta hai, jo ise tel ki tarah chikna bhi rakhta hai. Chalne-phirne aur exercise se ye fluid andar-bahar hota rehta hai. Budhaape mein cartilage patli hokar phat sakti hai, jisse joint akad jaata hai aur dard hota hai (osteoarthritis)."))
part('cruciate_ligaments', S, T("Where the cruciate ligaments attach", "क्रूसिएट लिगामेंट के जुड़ने की जगहें", "Cruciate ligaments ke judne ki jagah"),
  T("Spots inside the knee where two strong crossing bands, the cruciate ligaments, tie the thigh bone to the shin bone.", "घुटने के अंदर वे जगहें, जहाँ दो मज़बूत, एक-दूसरे को काटती पट्टियाँ, यानी क्रूसिएट लिगामेंट, जाँघ की हड्डी को पिंडली की हड्डी से बाँधती हैं।", "Ghutne ke andar wo jagah, jahan do mazboot, ek-doosre ko cross karti pattiyaan, yaani cruciate ligaments, thigh bone ko shin bone se baandhti hain."),
  T("The anterior and posterior cruciate ligaments cross like the letter X in the middle of the knee. They stop the shin bone sliding forwards or backwards under the thigh bone. A torn anterior cruciate ligament (ACL) is a common sports injury.",
    "अग्र और पश्च क्रूसिएट लिगामेंट घुटने के बीच में अंग्रेज़ी के X अक्षर की तरह एक-दूसरे को काटते हैं। ये पिंडली की हड्डी को जाँघ की हड्डी के नीचे आगे या पीछे फिसलने से रोकते हैं। अग्र क्रूसिएट लिगामेंट (ACL) का फटना खेल की एक आम चोट है।",
    "Anterior aur posterior cruciate ligaments ghutne ke beech mein English ke X letter ki tarah ek-doosre ko cross karte hain. Ye shin bone ko thigh bone ke neeche aage ya peeche phisalne se rokte hain. ACL (anterior cruciate ligament) ka phatna sports ki ek aam chot hai."))
part('collateral_ligaments', S, T("Where the side (collateral) ligaments attach", "पार्श्व (कोलैटरल) लिगामेंट के जुड़ने की जगहें", "Side (collateral) ligaments ke judne ki jagah"),
  T("Spots on the sides of the thigh bone where two side ligaments start; they stop the knee bending sideways.", "जाँघ की हड्डी के दोनों किनारों पर वे जगहें, जहाँ से दो पार्श्व लिगामेंट शुरू होते हैं; ये घुटने को किनारे की ओर मुड़ने से रोकते हैं।", "Thigh bone ke dono kinaaron par wo jagah, jahan se do side ligaments shuru hote hain; ye ghutne ko side ki taraf mudne se rokte hain."),
  T("The inner (medial) collateral ligament runs down to the shin bone and the outer (lateral) one to the fibula. Together they keep the knee working like a hinge: it bends forwards and backwards, but not from side to side.",
    "भीतरी (मीडियल) कोलैटरल लिगामेंट नीचे पिंडली की हड्डी तक और बाहरी (लैटरल) लिगामेंट फ़िबुला तक जाता है। ये मिलकर घुटने को कब्ज़े (हिंज) की तरह चलाते हैं: यह आगे-पीछे मुड़ता है, पर दाएँ-बाएँ नहीं।",
    "Andar wala (medial) collateral ligament neeche shin bone tak aur bahar wala (lateral) fibula tak jaata hai. Ye milkar ghutne ko hinge ki tarah chalate hain: ye aage-peeche mudta hai, par daayein-baayein nahi."))
part('knee_tendons', S, T("Tendons of the kneecap", "घुटने की टोपी के कंडरा (टेंडन)", "Kneecap ke tendons"),
  T("Strong cords above and below the kneecap that pass the pull of the big thigh muscle on to the shin bone.", "घुटने की टोपी के ऊपर और नीचे मज़बूत डोरियाँ, जो जाँघ की बड़ी मांसपेशी का खिंचाव पिंडली की हड्डी तक पहुँचाती हैं।", "Kneecap ke upar aur neeche mazboot doriyaan, jo thigh ki badi muscle ka khinchaav shin bone tak pahunchati hain."),
  T("The quadriceps tendon joins the thigh muscle to the top of the kneecap, and the patellar tendon joins the bottom of the kneecap to a bump on the front of the shin bone. When the thigh muscle tightens, it pulls through them and straightens the leg. A doctor taps the patellar tendon with a small hammer to test the knee-jerk reflex.",
    "क्वाड्रिसेप्स कंडरा जाँघ की मांसपेशी को घुटने की टोपी के ऊपरी भाग से जोड़ता है, और पटेलर कंडरा टोपी के निचले भाग को पिंडली की हड्डी के आगे के एक उभार से जोड़ता है। जब जाँघ की मांसपेशी कसती है, तो इन्हीं से खींचकर पैर सीधा करती है। डॉक्टर छोटी हथौड़ी से पटेलर कंडरा को थपथपाकर घुटने की प्रतिवर्ती क्रिया (नी-जर्क रिफ़्लेक्स) जाँचते हैं।",
    "Quadriceps tendon thigh ki muscle ko kneecap ke upar wale hisse se jodta hai, aur patellar tendon kneecap ke neeche wale hisse ko shin bone ke aage ke ek ubhaar se jodta hai. Jab thigh ki muscle kasti hai, to inhi se kheenchkar pair seedha karti hai. Doctor chhoti hathaudi se patellar tendon ko thapthapa kar knee-jerk reflex check karte hain."))
# ---------------------------------------------------------------- liver
part('liver_right_lobe', D, T("Right lobe of the liver", "यकृत का दायाँ पालि (राइट लोब)", "Liver ka right lobe"),
  T("The larger, right part of the liver, divided into four segments, each with its own blood supply and bile drainage.", "यकृत (लिवर) का बड़ा, दाहिना भाग, जो चार खंडों (सेगमेंट) में बँटा है; हर खंड की अपनी रक्त आपूर्ति और पित्त निकासी होती है।", "Liver ka bada, right hissa, jo chaar segments mein bata hai; har segment ki apni blood supply aur bile nikaasi hoti hai."),
  T("Surgeons divide the liver into eight segments by its blood vessels; the colours on this model show them. Because each segment works on its own, a damaged segment can be removed, and the rest of the liver grows back to almost full size within weeks.",
    "सर्जन लिवर को उसकी रक्त वाहिकाओं के आधार पर आठ खंडों में बाँटते हैं; इस मॉडल के रंग इन्हीं खंडों को दिखाते हैं। क्योंकि हर खंड अपने आप काम करता है, इसलिए ख़राब खंड निकाला जा सकता है, और बचा हुआ लिवर कुछ ही हफ़्तों में फिर लगभग पूरे आकार का हो जाता है।",
    "Surgeon liver ko uski blood vessels ke hisaab se aath segments mein baant-te hain; is model ke rang inhi segments ko dikhate hain. Kyunki har segment apne aap kaam karta hai, isliye kharaab segment nikaala ja sakta hai, aur bacha hua liver kuch hi hafton mein phir lagbhag poore size ka ho jaata hai."))
part('liver_left_lobe', D, T("Left lobe of the liver", "यकृत का बायाँ पालि (लेफ़्ट लोब)", "Liver ka left lobe"),
  T("The smaller, thinner part of the liver that reaches across to the left, over the stomach.", "लिवर का छोटा, पतला भाग, जो बाईं ओर आमाशय के ऊपर तक फैला रहता है।", "Liver ka chhota, patla hissa, jo left side mein stomach ke upar tak phaila rehta hai."),
  T("On the front, the falciform ligament marks the border between the left and right lobes. The left lobe is thin and flat; its underside rests on the stomach. Like the right lobe it makes bile, stores sugar as glycogen and cleans the blood.",
    "आगे की ओर फ़ैल्सीफ़ॉर्म लिगामेंट बाएँ और दाएँ पालि के बीच की सीमा दिखाता है। बायाँ पालि पतला और चपटा होता है; इसका निचला भाग आमाशय पर टिका रहता है। दाएँ पालि की तरह यह भी पित्त बनाता है, शक्कर को ग्लाइकोजन के रूप में जमा करता है और रक्त साफ़ करता है।",
    "Aage ki taraf falciform ligament left aur right lobe ke beech ki seema dikhata hai. Left lobe patla aur chapta hota hai; iska neeche wala hissa stomach par tika rehta hai. Right lobe ki tarah ye bhi bile banata hai, sugar ko glycogen ke roop mein store karta hai aur blood saaf karta hai."))
part('caudate_lobe', D, T("Caudate lobe", "पुच्छल पालि (कॉडेट लोब)", "Caudate lobe"),
  T("A small lobe at the back of the liver, beside the big vein (inferior vena cava) that carries blood back to the heart.", "लिवर के पीछे एक छोटा पालि, उस बड़ी शिरा (इन्फ़ीरियर वेना कावा) के पास, जो रक्त को वापस हृदय तक ले जाती है।", "Liver ke peeche ek chhota lobe, us badi vein (inferior vena cava) ke paas, jo blood ko wapas heart tak le jaati hai."),
  T("The caudate lobe gets blood from both the left and the right side of the liver and drains straight into the vena cava. So when other parts of the liver are damaged, this lobe often keeps working and grows larger.",
    "पुच्छल पालि को लिवर के बाएँ और दाएँ, दोनों भागों से रक्त मिलता है और इसका रक्त सीधे वेना कावा में जाता है। इसलिए जब लिवर के दूसरे भाग ख़राब होते हैं, तब भी यह पालि अक्सर काम करता रहता है और बड़ा हो जाता है।",
    "Caudate lobe ko liver ke left aur right, dono hisson se blood milta hai aur iska blood seedhe vena cava mein jaata hai. Isliye jab liver ke doosre hisse kharaab hote hain, tab bhi ye lobe aksar kaam karta rehta hai aur bada ho jaata hai."))
part('quadrate_lobe', D, T("Quadrate lobe", "चतुष्कोणी पालि (क्वाड्रेट लोब)", "Quadrate lobe"),
  T("A square-shaped lobe on the underside of the liver, between the gallbladder and the round ligament.", "लिवर के निचले भाग पर एक चौकोर पालि, पित्ताशय (गॉलब्लैडर) और गोल लिगामेंट के बीच।", "Liver ke neeche wale hisse par ek chaukor lobe, gallbladder aur round ligament ke beech."),
  T("Seen from below, the liver looks like the letter H: the quadrate lobe sits in front of the doorway (porta hepatis) and the caudate lobe behind it. The quadrate lobe works like the left lobe, to which it belongs by its blood supply.",
    "नीचे से देखने पर लिवर अंग्रेज़ी के H अक्षर जैसा दिखता है: चतुष्कोणी पालि द्वार (पोर्टा हेपेटिस) के आगे होता है और पुच्छल पालि उसके पीछे। चतुष्कोणी पालि बाएँ पालि की तरह काम करता है, क्योंकि रक्त आपूर्ति के हिसाब से यह उसी का भाग है।",
    "Neeche se dekhne par liver English ke H letter jaisa dikhta hai: quadrate lobe darwaze (porta hepatis) ke aage hota hai aur caudate lobe uske peeche. Quadrate lobe left lobe ki tarah kaam karta hai, kyunki blood supply ke hisaab se ye usi ka hissa hai."))
part('liver_ligaments', D, T("Ligaments of the liver", "यकृत के लिगामेंट", "Liver ke ligaments"),
  T("Folds and bands that hold the liver to the diaphragm and to the front wall of the belly.", "झिल्लियों की तहें और पट्टियाँ, जो लिवर को डायाफ्राम (मध्यपट) और पेट की आगे की दीवार से थामे रखती हैं।", "Jhilliyon ki tahein aur pattiyaan, jo liver ko diaphragm aur pet ki aage ki deewar se thaame rakhti hain."),
  T("The sickle-shaped falciform ligament runs over the front; the round ligament along its edge is all that is left of the vein that brought blood from the mother to the baby before birth. The coronary and triangular ligaments hang the liver from the diaphragm, so it moves up and down as we breathe.",
    "हँसिए के आकार का फ़ैल्सीफ़ॉर्म लिगामेंट आगे की ओर से गुज़रता है; इसके किनारे का गोल लिगामेंट उस शिरा का बचा हुआ भाग है, जो जन्म से पहले माँ से बच्चे तक रक्त लाती थी। कोरोनरी और त्रिकोणीय लिगामेंट लिवर को डायाफ्राम से लटकाए रखते हैं, इसलिए साँस लेते समय लिवर ऊपर-नीचे होता है।",
    "Hansiye ke shape ka falciform ligament aage ki taraf se guzarta hai; iske kinaare ka round ligament us vein ka bacha hua hissa hai, jo janam se pehle maa se bachche tak blood laati thi. Coronary aur triangular ligaments liver ko diaphragm se latkaaye rakhte hain, isliye saans lete samay liver upar-neeche hota hai."))
part('porta_hepatis', D, T("Doorway of the liver (porta hepatis)", "यकृत का द्वार (पोर्टा हेपेटिस)", "Liver ka darwaza (porta hepatis)"),
  T("The opening on the underside of the liver where blood comes in and bile goes out.", "लिवर के निचले भाग पर वह द्वार, जहाँ से रक्त अंदर आता है और पित्त बाहर जाता है।", "Liver ke neeche wale hisse par wo darwaza, jahan se blood andar aata hai aur bile bahar jaata hai."),
  T("Two blood vessels enter here: the hepatic artery brings oxygen-rich blood, and the portal vein brings blood full of digested food from the stomach and intestines. The liver stores and changes this food and removes harmful substances. Bile leaves through the bile ducts on its way to the gallbladder and the duodenum.",
    "यहाँ से दो रक्त वाहिकाएँ अंदर आती हैं: यकृत धमनी (हेपेटिक आर्टरी) ऑक्सीजन वाला रक्त लाती है, और निवाहिका शिरा (पोर्टल वेन) आमाशय और आँतों से पचे भोजन से भरा रक्त लाती है। लिवर इस भोजन को जमा करता है, बदलता है और हानिकारक पदार्थ हटाता है। पित्त, पित्त नलियों से होकर पित्ताशय और ग्रहणी की ओर निकलता है।",
    "Yahan se do blood vessels andar aati hain: hepatic artery oxygen wala blood laati hai, aur portal vein stomach aur intestines se pache khaane se bhara blood laati hai. Liver is khaane ko store karta hai, badalta hai aur harmful cheezein hataata hai. Bile, bile ducts se hokar gallbladder aur duodenum ki taraf nikalta hai."))
part('liver_impressions', D, T("Marks of the neighbours (impressions)", "पड़ोसी अंगों के निशान (इम्प्रेशन)", "Padosi organs ke nishaan (impressions)"),
  T("Shallow hollows on the underside of the soft liver, pressed in by the stomach, kidney, colon, duodenum and adrenal gland.", "नरम लिवर के निचले भाग पर उथले गड्ढे, जो आमाशय, वृक्क, बड़ी आँत, ग्रहणी और अधिवृक्क ग्रंथि के दबाव से बनते हैं।", "Naram liver ke neeche wale hisse par uthle gaddhe, jo stomach, kidney, colon, duodenum aur adrenal gland ke dabaav se bante hain."),
  T("The liver is soft and fills the space under the right side of the diaphragm, so the organs packed around it leave their shapes on it. The marks show which organs touch the liver: the organs of the belly fit together tightly, like the pieces of a puzzle.",
    "लिवर नरम है और डायाफ्राम के दाएँ भाग के नीचे की जगह भरता है, इसलिए इसके चारों ओर सटे अंग इस पर अपनी आकृति छोड़ देते हैं। ये निशान बताते हैं कि कौन-से अंग लिवर को छूते हैं: पेट के अंग पहेली के टुकड़ों की तरह कसकर एक-दूसरे में फ़िट रहते हैं।",
    "Liver naram hai aur diaphragm ke right hisse ke neeche ki jagah bharta hai, isliye iske chaaron taraf sate organs is par apni shape chhod dete hain. Ye nishaan batate hain ki kaun-se organs liver ko chhoote hain: pet ke organs puzzle ke tukdon ki tarah kaskar ek-doosre mein fit rehte hain."))
# ---------------------------------------------------------------- steps
ST = {}
def step(k, title, text): ST[k] = {'title': title, 'text': text}
step('lab-mouth-1', T("The mouth: where digestion begins", "मुँह: जहाँ पाचन शुरू होता है", "Munh: jahan digestion shuru hota hai"),
  T("Digestion begins the moment food enters the mouth. Teeth break it into small pieces, saliva wets it and starts digesting starch, and the tongue mixes it and shapes it into a soft ball that is easy to swallow.",
    "भोजन मुँह में आते ही पाचन शुरू हो जाता है। दाँत इसे छोटे टुकड़ों में तोड़ते हैं, लार इसे गीला करती है और स्टार्च को पचाना शुरू करती है, और जीभ इसे मिलाकर एक नरम गोला बनाती है, जिसे निगलना आसान होता है।",
    "Khaana munh mein aate hi digestion shuru ho jaata hai. Daant ise chhote tukdon mein todte hain, saliva ise geela karti hai aur starch ko pachana shuru karti hai, aur jeebh ise milaakar ek naram gola banati hai, jise nigalna aasaan hota hai."))
step('lab-mouth-2', T("Teeth: cut, tear and grind", "दाँत: काटना, फाड़ना और पीसना", "Daant: kaatna, phaadna aur peesna"),
  T("Each kind of tooth has its own job. Incisors at the front cut a bite of roti, canines tear tough food, and premolars and molars at the back crush and grind it. The teeth sit in the jaw bone, held firmly by the gums. Chewing well gives the digestive juices more surface to work on.",
    "हर तरह के दाँत का अपना काम है। आगे के कृंतक (इनसाइज़र) रोटी का टुकड़ा काटते हैं, रदनक (कैनाइन) सख़्त भोजन फाड़ते हैं, और पीछे के अग्रचर्वणक और चर्वणक उसे कुचलते और पीसते हैं। दाँत जबड़े की हड्डी में लगे रहते हैं और मसूड़े उन्हें कसकर थामे रखते हैं। अच्छी तरह चबाने से पाचक रसों को काम करने के लिए ज़्यादा सतह मिलती है।",
    "Har tarah ke daant ka apna kaam hai. Aage ke incisors roti ka tukda kaat-te hain, canines sakht khaana phaadte hain, aur peeche ke premolars aur molars use kuchalte aur peeste hain. Daant jabde ki haddi mein lage rehte hain aur masoode unhe kaskar thaame rakhte hain. Achchhi tarah chabaane se digestive juices ko kaam karne ke liye zyaada surface milta hai."))
step('lab-mouth-3', T("Saliva from three pairs of glands", "तीन जोड़ी ग्रंथियों से लार", "Teen jodi glands se saliva"),
  T("Three pairs of salivary glands make about one to one and a half litres of saliva a day. The parotid glands in front of the ears, the submandibular glands under the jaw and the sublingual glands under the tongue pour it in through ducts. Saliva wets food, and its enzyme, salivary amylase, starts breaking starch into sugar. That is why a roti tastes sweet if you chew it for a long time.",
    "तीन जोड़ी लार ग्रंथियाँ रोज़ लगभग एक से डेढ़ लीटर लार बनाती हैं। कानों के आगे कर्णपूर्व ग्रंथियाँ (पैरोटिड), जबड़े के नीचे अधोहनु ग्रंथियाँ (सबमैंडिबुलर) और जीभ के नीचे अधोजिह्वा ग्रंथियाँ (सबलिंगुअल) नलियों से लार मुँह में डालती हैं। लार भोजन को गीला करती है, और इसका एंज़ाइम, लार एमाइलेज़, स्टार्च को शक्कर में तोड़ना शुरू करता है। इसीलिए रोटी को देर तक चबाने पर वह मीठी लगती है।",
    "Teen jodi salivary glands roz lagbhag ek se dedh litre saliva banati hain. Kaanon ke aage parotid glands, jabde ke neeche submandibular glands aur jeebh ke neeche sublingual glands naliyon se saliva munh mein daalti hain. Saliva khaane ko geela karti hai, aur iska enzyme, salivary amylase, starch ko sugar mein todna shuru karta hai. Isiliye roti ko der tak chabaane par wo meethi lagti hai."))
step('lab-mouth-4', T("The tongue and taste", "जीभ और स्वाद", "Jeebh aur swaad"),
  T("The tongue is a bundle of muscles that turns food around while we chew and mixes it with saliva. Its top is covered with small bumps, the papillae, which hold thousands of taste buds. They sense sweet, salty, sour, bitter and umami, and together with smell they tell us whether food is good to eat.",
    "जीभ मांसपेशियों का एक गुच्छा है, जो चबाते समय भोजन को उलटती-पलटती है और उसमें लार मिलाती है। इसकी ऊपरी सतह छोटे उभारों, यानी पैपिला, से ढकी होती है, जिनमें हज़ारों स्वाद कलिकाएँ होती हैं। ये मीठा, नमकीन, खट्टा, कड़वा और उमामी स्वाद पहचानती हैं, और गंध के साथ मिलकर बताती हैं कि भोजन खाने लायक है या नहीं।",
    "Jeebh muscles ka ek guchchha hai, jo chabaate samay khaane ko ulat-palat karti hai aur usmein saliva milaati hai. Iski upar ki surface chhote ubhaaron, yaani papillae, se dhaki hoti hai, jinmein hazaaron taste buds hote hain. Ye meetha, namkeen, khatta, kadwa aur umami swaad pehchaante hain, aur smell ke saath milkar batate hain ki khaana khaane laayak hai ya nahi."))
step('lab-mouth-5', T("The roof of the mouth", "मुँह की छत", "Munh ki chhat"),
  T("The model is cut down the middle so we can look inside. The roof of the mouth is the palate. Its front, the hard palate, is bone; the tongue presses food against it. Its back, the soft palate, is muscle; when we swallow, it lifts up and closes the way into the nose, so food does not go up the nose.",
    "मॉडल को बीच से काटा गया है, ताकि हम अंदर देख सकें। मुँह की छत को तालु कहते हैं। इसका अगला भाग, कठोर तालु, हड्डी का बना है; जीभ भोजन को इससे दबाती है। पिछला भाग, कोमल तालु, मांसपेशी का बना है; निगलते समय यह ऊपर उठकर नाक का रास्ता बंद कर देता है, ताकि भोजन नाक में न चढ़े।",
    "Model ko beech se kaata gaya hai, taaki hum andar dekh sakein. Munh ki chhat ko palate (taalu) kehte hain. Iska agla hissa, hard palate, haddi ka bana hai; jeebh khaane ko isse dabaati hai. Peechhla hissa, soft palate, muscle ka bana hai; nigalte samay ye upar uthkar naak ka raasta band kar deta hai, taaki khaana naak mein na chadhe."))
step('lab-mouth-6', T("Swallowing", "निगलना", "Nigalna"),
  T("When the food ball, the bolus, is ready, the tongue presses up and back and pushes it into the throat. From here swallowing happens by itself: the soft palate closes the nose, a flap (the epiglottis) closes the windpipe, and the food pipe carries the bolus down to the stomach in waves of muscle (peristalsis).",
    "जब भोजन का गोला, यानी बोलस, तैयार हो जाता है, तो जीभ ऊपर और पीछे दबाकर उसे गले में धकेल देती है। इसके बाद निगलना अपने आप होता है: कोमल तालु नाक को बंद करता है, एक ढक्कन (एपिग्लॉटिस) श्वास नली को बंद करता है, और भोजन नली मांसपेशियों की लहरों (क्रमाकुंचन, पेरिस्टैल्सिस) से बोलस को नीचे आमाशय तक ले जाती है।",
    "Jab khaane ka gola, yaani bolus, taiyaar ho jaata hai, to jeebh upar aur peeche dabaakar use gale mein dhakel deti hai. Iske baad nigalna apne aap hota hai: soft palate naak ko band karta hai, ek dhakkan (epiglottis) windpipe ko band karta hai, aur food pipe muscles ki lehron (peristalsis) se bolus ko neeche stomach tak le jaati hai."))
step('lab-gut-1', T("The intestines: a long, folded tube", "आँतें: एक लंबी, मुड़ी हुई नली", "Intestines: ek lambi, mudi hui nali"),
  T("After the stomach, food enters the intestines. The small intestine is about 6 metres long and the large intestine about 1.5 metres, yet they fit in the belly because they are folded many times. Waves of muscle in their walls (peristalsis) slowly push the food along.",
    "आमाशय के बाद भोजन आँतों में जाता है। छोटी आँत लगभग 6 मीटर और बड़ी आँत लगभग 1.5 मीटर लंबी होती है, फिर भी ये पेट में समा जाती हैं, क्योंकि ये कई बार मुड़ी होती हैं। इनकी दीवारों में मांसपेशियों की लहरें (क्रमाकुंचन, पेरिस्टैल्सिस) भोजन को धीरे-धीरे आगे बढ़ाती हैं।",
    "Stomach ke baad khaana intestines mein jaata hai. Small intestine lagbhag 6 metre aur large intestine lagbhag 1.5 metre lambi hoti hai, phir bhi ye pet mein sama jaati hain, kyunki ye kai baar mudi hoti hain. Inki deewaron mein muscles ki lehrein (peristalsis) khaane ko dheere-dheere aage badhati hain."))
step('lab-gut-2', T("Duodenum: the juices join in", "ग्रहणी: पाचक रस आकर मिलते हैं", "Duodenum: digestive juices aakar milte hain"),
  T("The first part of the small intestine, the C-shaped duodenum, receives the half-digested food from the stomach. Through one small opening, bile from the liver and pancreatic juice pour in. Bile breaks fat into tiny droplets, and the pancreatic juice digests starch, proteins and fats.",
    "छोटी आँत का पहला भाग, C आकार की ग्रहणी (ड्यूडेनम), आमाशय से आधा पचा भोजन लेती है। एक छोटे द्वार से लिवर का पित्त और अग्न्याशय का रस इसमें आते हैं। पित्त वसा को छोटी-छोटी बूँदों में तोड़ता है, और अग्न्याशय रस स्टार्च, प्रोटीन और वसा को पचाता है।",
    "Small intestine ka pehla hissa, C shape ka duodenum, stomach se aadha pacha khaana leta hai. Ek chhote darwaze se liver ka bile aur pancreas ka juice ismein aate hain. Bile fat ko chhoti-chhoti boondon mein todta hai, aur pancreatic juice starch, proteins aur fats ko pachata hai."))
step('lab-gut-3', T("Jejunum and ileum: food goes into the blood", "मध्यांत्र और शेषांत्र: भोजन रक्त में जाता है", "Jejunum aur ileum: khaana blood mein jaata hai"),
  T("In the jejunum and ileum digestion is completed and the food is absorbed. Look through the magnifier: the inner wall is covered with millions of tiny villi. They make the surface as big as a badminton court, so sugars, amino acids and fats pass quickly into the blood and lymph.",
    "मध्यांत्र और शेषांत्र में पाचन पूरा होता है और भोजन अवशोषित होता है। आवर्धक लेंस (मैग्नीफ़ायर) से देखिए: अंदर की दीवार लाखों छोटे विलाई से ढकी है। इनसे सतह एक बैडमिंटन कोर्ट जितनी बड़ी हो जाती है, ताकि शक्कर, अमीनो एसिड और वसा जल्दी से रक्त और लसीका में चले जाएँ।",
    "Jejunum aur ileum mein digestion poora hota hai aur khaana absorb hota hai. Magnifier se dekhiye: andar ki deewar laakhon chhote villi se dhaki hai. Inse surface ek badminton court jitni badi ho jaati hai, taaki sugar, amino acids aur fat jaldi se blood aur lymph mein chale jaayein."))
step('lab-gut-4', T("Through the gate into the large intestine", "दरवाज़े से बड़ी आँत में", "Darwaze se large intestine mein"),
  T("What cannot be digested, like fibre, reaches the end of the ileum together with water. The ileocaecal valve lets it pass into the caecum, the pouch at the start of the large intestine, and stops it from coming back. The narrow appendix hangs from the caecum.",
    "जो पच नहीं सकता, जैसे रेशा (फ़ाइबर), वह पानी के साथ शेषांत्र के अंत तक पहुँचता है। इलियोसीकल वाल्व इसे बड़ी आँत की शुरुआत की थैली, अंधनाल (सीकम), में जाने देता है और वापस नहीं आने देता। अंधनाल से पतली परिशेषिका (अपेंडिक्स) लटकती है।",
    "Jo pach nahi sakta, jaise fibre, wo paani ke saath ileum ke end tak pahunchta hai. Ileocaecal valve ise large intestine ki shuruaat ki thaili, caecum, mein jaane deta hai aur wapas nahi aane deta. Caecum se patla appendix latakta hai."))
step('lab-gut-5', T("The colon takes back water", "बृहदांत्र (कोलन) पानी वापस लेता है", "Colon paani wapas leta hai"),
  T("The colon goes up the right side, across the top and down the left side of the belly. As the waste moves slowly along, the colon takes back most of the water and salts, and the waste becomes solid stool. Trillions of helpful bacteria live here; they break down some fibre and make vitamin K.",
    "बृहदांत्र (कोलन) पेट के दाएँ भाग से ऊपर जाता है, ऊपर से आर-पार जाता है और बाएँ भाग से नीचे आता है। जैसे-जैसे कचरा धीरे-धीरे आगे बढ़ता है, कोलन ज़्यादातर पानी और लवण वापस सोख लेता है, और कचरा ठोस मल बन जाता है। यहाँ खरबों उपयोगी बैक्टीरिया रहते हैं; ये कुछ रेशे को तोड़ते हैं और विटामिन K बनाते हैं।",
    "Colon pet ke right hisse se upar jaata hai, upar se aar-paar jaata hai aur left hisse se neeche aata hai. Jaise-jaise waste dheere-dheere aage badhta hai, colon zyaadatar paani aur salts wapas sokh leta hai, aur waste solid stool ban jaata hai. Yahan kharbon useful bacteria rehte hain; ye kuch fibre ko todte hain aur vitamin K banate hain."))
step('lab-gut-6', T("Rectum: out of the body", "मलाशय: शरीर से बाहर", "Rectum: body se bahar"),
  T("The S-shaped sigmoid colon leads to the rectum, where stool is stored. When the rectum is full, we feel the urge to go to the toilet, and the stool is passed out through the anus (egestion). Eating fibre-rich food and drinking enough water keep this journey smooth.",
    "S आकार का सिग्मॉइड कोलन मलाशय (रेक्टम) तक जाता है, जहाँ मल जमा रहता है। जब मलाशय भर जाता है, तो हमें शौचालय जाने की इच्छा होती है, और मल गुदा (एनस) से बाहर निकल जाता है (बहिःक्षेपण, इजेशन)। रेशे वाला भोजन खाने और पर्याप्त पानी पीने से यह यात्रा आसान रहती है।",
    "S shape ka sigmoid colon rectum tak jaata hai, jahan stool store rehta hai. Jab rectum bhar jaata hai, to humein toilet jaane ki ichchha hoti hai, aur stool anus se bahar nikal jaata hai (egestion). Fibre wala khaana khaane aur kaafi paani peene se ye journey aasaan rehti hai."))
step('lab-liver-1', T("The liver: the body's chemical factory", "लिवर: शरीर का रासायनिक कारख़ाना", "Liver: body ki chemical factory"),
  T("The liver is the largest gland of the body. It weighs about one and a half kilograms and sits in the upper right of the belly, under the diaphragm. It does more than 500 jobs: it makes bile, stores sugar, vitamins and iron, makes proteins for the blood and removes poisons.",
    "यकृत (लिवर) शरीर की सबसे बड़ी ग्रंथि है। इसका वज़न लगभग डेढ़ किलोग्राम होता है और यह पेट के ऊपरी दाएँ भाग में, डायाफ्राम के नीचे होता है। यह 500 से ज़्यादा काम करता है: पित्त बनाता है, शक्कर, विटामिन और आयरन जमा करता है, रक्त के लिए प्रोटीन बनाता है और ज़हरीले पदार्थ हटाता है।",
    "Liver body ki sabse badi gland hai. Iska wazan lagbhag dedh kilogram hota hai aur ye pet ke upar right hisse mein, diaphragm ke neeche hota hai. Ye 500 se zyaada kaam karta hai: bile banata hai, sugar, vitamins aur iron store karta hai, blood ke liye proteins banata hai aur zehreele padarth hataata hai."))
step('lab-liver-2', T("Four lobes, eight segments", "चार पालि, आठ खंड", "Chaar lobes, aath segments"),
  T("From the front we see a big right lobe and a smaller left lobe. Turned over, two more small lobes appear underneath: the square quadrate lobe and the caudate lobe at the back. The colours show the eight segments that doctors use; each has its own blood vessels and bile duct.",
    "आगे से एक बड़ा दायाँ पालि और एक छोटा बायाँ पालि दिखता है। पलटने पर नीचे दो और छोटे पालि दिखते हैं: चौकोर चतुष्कोणी पालि और पीछे की ओर पुच्छल पालि। रंग उन आठ खंडों को दिखाते हैं, जिनका इस्तेमाल डॉक्टर करते हैं; हर खंड की अपनी रक्त वाहिकाएँ और पित्त नली होती है।",
    "Aage se ek bada right lobe aur ek chhota left lobe dikhta hai. Palatne par neeche do aur chhote lobes dikhte hain: chaukor quadrate lobe aur peeche ki taraf caudate lobe. Rang un aath segments ko dikhate hain, jinka use doctor karte hain; har segment ki apni blood vessels aur bile duct hoti hai."))
step('lab-liver-3', T("The doorway of the liver", "लिवर का द्वार", "Liver ka darwaza"),
  T("On the underside is the porta hepatis, the liver's doorway. The portal vein brings in blood from the stomach and intestines, full of digested food, and the hepatic artery brings oxygen. The liver takes what the body needs from this blood, stores the rest and makes harmful substances harmless.",
    "निचले भाग पर लिवर का द्वार, पोर्टा हेपेटिस, है। निवाहिका शिरा (पोर्टल वेन) आमाशय और आँतों से पचे भोजन से भरा रक्त लाती है, और यकृत धमनी ऑक्सीजन लाती है। लिवर इस रक्त से शरीर की ज़रूरत की चीज़ें लेता है, बाक़ी को जमा करता है और हानिकारक पदार्थों को हानिरहित बनाता है।",
    "Neeche wale hisse par liver ka darwaza, porta hepatis, hai. Portal vein stomach aur intestines se pache khaane se bhara blood laati hai, aur hepatic artery oxygen laati hai. Liver is blood se body ki zaroorat ki cheezein leta hai, baaki ko store karta hai aur harmful padarthon ko harmless banata hai."))
step('lab-liver-4', T("Bile for digesting fat", "वसा पचाने के लिए पित्त", "Fat pachane ke liye bile"),
  T("Liver cells make about half a litre to one litre of greenish-yellow bile every day. It flows out through the bile ducts and is stored in the gallbladder. When fatty food reaches the duodenum, the gallbladder squeezes bile in. Bile has no enzymes; it breaks fat into tiny droplets (emulsification), so enzymes can digest it fast.",
    "लिवर की कोशिकाएँ रोज़ लगभग आधा से एक लीटर हरा-पीला पित्त बनाती हैं। यह पित्त नलियों से बाहर निकलकर पित्ताशय (गॉलब्लैडर) में जमा होता है। जब वसा वाला भोजन ग्रहणी में पहुँचता है, तो पित्ताशय सिकुड़कर पित्त उसमें डालता है। पित्त में कोई एंज़ाइम नहीं होता; यह वसा को छोटी-छोटी बूँदों में तोड़ता है (पायसीकरण, इमल्सीफ़िकेशन), ताकि एंज़ाइम उसे जल्दी पचा सकें।",
    "Liver ki cells roz lagbhag aadha se ek litre hara-peela bile banati hain. Ye bile ducts se bahar nikalkar gallbladder mein store hota hai. Jab fat wala khaana duodenum mein pahunchta hai, to gallbladder sikudkar bile usmein daalta hai. Bile mein koi enzyme nahi hota; ye fat ko chhoti-chhoti boondon mein todta hai (emulsification), taaki enzymes use jaldi pacha sakein."))
step('lab-liver-5', T("Shaped by its neighbours", "पड़ोसियों से बनी आकृति", "Padosiyon se bani shape"),
  T("The soft liver carries marks of the organs that press against it: the stomach, the right kidney, the colon and the duodenum. The liver can also do something no other organ can: if part of it is removed, the rest grows back. Avoiding alcohol and too much fried food keeps it healthy.",
    "नरम लिवर पर उन अंगों के निशान होते हैं, जो इससे सटे रहते हैं: आमाशय, दायाँ वृक्क, बड़ी आँत और ग्रहणी। लिवर एक ऐसा काम भी कर सकता है, जो कोई दूसरा अंग नहीं कर सकता: अगर इसका कुछ भाग निकाल दिया जाए, तो बाक़ी भाग फिर से बढ़ जाता है। शराब और ज़्यादा तली-भुनी चीज़ों से दूर रहने से लिवर स्वस्थ रहता है।",
    "Naram liver par un organs ke nishaan hote hain, jo isse sate rehte hain: stomach, right kidney, colon aur duodenum. Liver ek aisa kaam bhi kar sakta hai, jo koi doosra organ nahi kar sakta: agar iska kuch hissa nikaal diya jaaye, to baaki hissa phir se badh jaata hai. Sharaab aur zyaada tali-bhuni cheezon se door rehne se liver healthy rehta hai."))
step('lab-knee-1', T("The knee: the body's biggest joint", "घुटना: शरीर का सबसे बड़ा जोड़", "Ghutna: body ka sabse bada joint"),
  T("The knee joins the thigh bone (femur) to the shin bone (tibia). The thin fibula runs beside the tibia, and the kneecap (patella) protects the front. It is a hinge joint: like a door hinge it lets the leg bend and straighten, and it carries the whole weight of the body when we stand, walk and jump.",
    "घुटना जाँघ की हड्डी (फ़ीमर) को पिंडली की हड्डी (टिबिया) से जोड़ता है। पतली फ़िबुला टिबिया के बगल में रहती है, और घुटने की टोपी (पटेला) आगे से रक्षा करती है। यह कब्ज़ा जोड़ (हिंज जॉइंट) है: दरवाज़े के कब्ज़े की तरह यह पैर को मुड़ने और सीधा होने देता है, और खड़े होने, चलने और कूदने पर शरीर का पूरा भार उठाता है।",
    "Ghutna thigh bone (femur) ko shin bone (tibia) se jodta hai. Patli fibula tibia ke bagal mein rehti hai, aur kneecap (patella) aage se protect karti hai. Ye hinge joint hai: darwaze ke hinge ki tarah ye pair ko mudne aur seedha hone deta hai, aur khade hone, chalne aur koodne par body ka poora weight uthata hai."))
step('lab-knee-2', T("Smooth cartilage and cushions", "चिकनी उपास्थि और गद्दियाँ", "Chikni cartilage aur cushions"),
  T("With the kneecap set aside, we see the ends of the bones. They are covered with smooth, glassy cartilage, oiled by synovial fluid, so they glide with less friction than ice on ice. Between them lie the two C-shaped menisci, which cushion every step.",
    "घुटने की टोपी हटाने पर हड्डियों के सिरे दिखते हैं। ये चिकनी, काँच जैसी उपास्थि (कार्टिलेज) से ढके होते हैं, जिन्हें सायनोवियल द्रव चिकना रखता है, इसलिए ये बर्फ़ पर बर्फ़ से भी कम घर्षण के साथ फिसलते हैं। इनके बीच दो C आकार के मेनिस्कस होते हैं, जो हर क़दम के झटके को सोखते हैं।",
    "Kneecap hataane par haddiyon ke sire dikhte hain. Ye chikni, kaanch jaisi cartilage se dhake hote hain, jinhe synovial fluid chikna rakhta hai, isliye ye barf par barf se bhi kam friction ke saath phisalte hain. Inke beech do C shape ke menisci hote hain, jo har kadam ke jhatke ko sokhte hain."))
step('lab-knee-3', T("Ligaments tie the bones together", "लिगामेंट हड्डियों को बाँधते हैं", "Ligaments haddiyon ko baandhte hain"),
  T("Bones are tied to each other by ligaments, strong bands like ropes. The coloured patches show where the knee's ligaments are fixed. Two cruciate ligaments cross inside the joint and stop the bones sliding forwards and backwards; two collateral ligaments on the sides stop the knee bending sideways.",
    "हड्डियाँ लिगामेंट से एक-दूसरे से बँधी रहती हैं; ये रस्सी जैसी मज़बूत पट्टियाँ हैं। रंगीन धब्बे दिखाते हैं कि घुटने के लिगामेंट कहाँ जुड़े हैं। दो क्रूसिएट लिगामेंट जोड़ के अंदर एक-दूसरे को काटते हैं और हड्डियों को आगे-पीछे फिसलने से रोकते हैं; किनारों पर दो कोलैटरल लिगामेंट घुटने को दाएँ-बाएँ मुड़ने से रोकते हैं।",
    "Haddiyaan ligaments se ek-doosre se bandhi rehti hain; ye rassi jaisi mazboot pattiyaan hain. Rangeen dhabbe dikhate hain ki ghutne ke ligaments kahan jude hain. Do cruciate ligaments joint ke andar ek-doosre ko cross karte hain aur haddiyon ko aage-peeche phisalne se rokte hain; kinaaron par do collateral ligaments ghutne ko daayein-baayein mudne se rokte hain."))
step('lab-knee-4', T("Bending and straightening", "मुड़ना और सीधा होना", "Mudna aur seedha hona"),
  T("Watch the knee bend. The shin bone swings back while the rounded ends of the thigh bone roll and glide on it, and the kneecap slides down its groove. The big thigh muscle in front (quadriceps) pulls on the kneecap through a tendon to straighten the leg; muscles at the back bend it.",
    "घुटने को मुड़ते देखिए। पिंडली की हड्डी पीछे की ओर झूलती है, जबकि जाँघ की हड्डी के गोल सिरे उस पर लुढ़कते और फिसलते हैं, और घुटने की टोपी अपनी नाली में नीचे फिसलती है। आगे की जाँघ की बड़ी मांसपेशी (क्वाड्रिसेप्स) एक कंडरा (टेंडन) से घुटने की टोपी को खींचकर पैर सीधा करती है; पीछे की मांसपेशियाँ उसे मोड़ती हैं।",
    "Ghutne ko mudte dekhiye. Shin bone peeche ki taraf jhoolti hai, jabki thigh bone ke gol sire us par ludhakte aur phisalte hain, aur kneecap apni naali mein neeche phisalti hai. Aage ki thigh ki badi muscle (quadriceps) ek tendon se kneecap ko kheenchkar pair seedha karti hai; peeche ki muscles use modti hain."))
step('lab-knee-5', T("Keeping knees healthy", "घुटनों को स्वस्थ रखना", "Ghutnon ko healthy rakhna"),
  T("Every step puts two to three times the body's weight on the knees, and running even more. Regular exercise keeps the muscles strong and feeds the cartilage, and a healthy weight reduces the load. Warming up before games and landing softly on bent knees help prevent injuries to the menisci and ligaments.",
    "हर क़दम पर घुटनों पर शरीर के भार का दो से तीन गुना भार पड़ता है, और दौड़ने पर इससे भी ज़्यादा। नियमित व्यायाम मांसपेशियों को मज़बूत रखता है और उपास्थि को पोषण देता है, और सही वज़न से भार कम होता है। खेल से पहले वार्म-अप करने और कूदने के बाद मुड़े घुटनों पर धीरे से उतरने से मेनिस्कस और लिगामेंट की चोटों से बचाव होता है।",
    "Har kadam par ghutnon par body ke weight ka do se teen guna bhaar padta hai, aur daudne par isse bhi zyaada. Regular exercise muscles ko mazboot rakhta hai aur cartilage ko nutrition deta hai, aur sahi wazan se bhaar kam hota hai. Khel se pehle warm-up karne aur koodne ke baad mude ghutnon par dheere se utarne se meniscus aur ligament ki choton se bachaav hota hai."))

